-- Phase 13 Part 2: platform administrators and their operations.
-- Generated by prisma migrate diff, followed by a hand-written section.

-- CreateTable
CREATE TABLE "platform_admins" (
    "user_id" UUID NOT NULL,
    "note" TEXT,
    "granted_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "revoked_at" TIMESTAMPTZ(3),

    CONSTRAINT "platform_admins_pkey" PRIMARY KEY ("user_id")
);

-- AddForeignKey
ALTER TABLE "platform_admins" ADD CONSTRAINT "platform_admins_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- =============================================================================================
-- Hand-written below this line: platform administrators are granted and revoked only by an
-- operator (the database owner; see packages/db/scripts/platform-admin.ts). They read
-- organisations, subscriptions and their history across tenants and nothing else; they change
-- a subscription or suspend and reactivate an organisation only through the functions below,
-- which check the caller, act in that organisation's context and write its audit log. See
-- docs/security/ACCESS_CONTROL.md section 6.4b.
-- =============================================================================================

ALTER TABLE "platform_admins" ADD CONSTRAINT "platform_admins_note"
  CHECK ("note" IS NULL OR length(btrim("note")) BETWEEN 1 AND 200);

CREATE FUNCTION app_is_platform_admin() RETURNS boolean
  LANGUAGE sql STABLE
  AS $$
    SELECT EXISTS (SELECT 1 FROM "platform_admins"
                    WHERE "user_id" = app_current_user_id() AND "revoked_at" IS NULL)
  $$;

CREATE POLICY "organisations_platform_select" ON "organisations" FOR SELECT USING (app_is_platform_admin());
CREATE POLICY "subscriptions_platform_select" ON "subscriptions" FOR SELECT USING (app_is_platform_admin());
CREATE POLICY "subscription_events_platform_select" ON "subscription_events" FOR SELECT USING (app_is_platform_admin());

-- Runs a statement in an organisation's context for a platform administrator, then restores it.
CREATE FUNCTION app_platform_require() RETURNS void
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NOT app_is_platform_admin() THEN
    RAISE EXCEPTION 'platform administrators only' USING ERRCODE = 'insufficient_privilege';
  END IF;
END
$$;

-- Counts only (no tenant data): properties, active units and active members.
CREATE FUNCTION app_platform_usage(org uuid)
  RETURNS TABLE ("properties" int, "units" int, "members" int)
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
DECLARE
  prev text := current_setting('app.organisation_id', true);
BEGIN
  PERFORM app_platform_require();
  PERFORM set_config('app.organisation_id', org::text, true);
  RETURN QUERY
    SELECT (SELECT count(*) FROM "properties" WHERE "organisation_id" = org AND "status" <> 'ARCHIVED')::int,
           (SELECT count(*) FROM "units" WHERE "organisation_id" = org AND "status" = 'ACTIVE')::int,
           (SELECT count(DISTINCT "user_id") FROM "memberships" WHERE "organisation_id" = org AND "status" = 'ACTIVE')::int;
  PERFORM set_config('app.organisation_id', coalesce(prev, ''), true);
END
$$;

CREATE FUNCTION app_platform_set_subscription(org uuid, p_plan text, p_status "SubscriptionStatus",
                                              p_trial_ends timestamptz, p_reason text)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
DECLARE
  prev text := current_setting('app.organisation_id', true);
  before record;
BEGIN
  PERFORM app_platform_require();
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'give a reason' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('app.organisation_id', org::text, true);
  PERFORM set_config('app.subscription_reason', btrim(p_reason), true);
  SELECT * INTO before FROM "subscriptions" WHERE "organisation_id" = org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such organisation' USING ERRCODE = 'no_data_found';
  END IF;
  UPDATE "subscriptions"
     SET "plan_code" = p_plan, "status" = p_status,
         "trial_ends_at" = CASE WHEN p_status = 'TRIAL' THEN p_trial_ends END,
         "updated_at" = now()
   WHERE "organisation_id" = org;
  INSERT INTO "audit_logs" ("id", "organisation_id", "actor_user_id", "action", "resource_type", "resource_id", "metadata")
  VALUES (gen_random_uuid(), org, app_current_user_id(), 'subscription.changed', 'organisation', org::text,
          jsonb_build_object('fromPlan', before."plan_code", 'toPlan', p_plan,
                             'fromStatus', before."status", 'toStatus', p_status, 'reason', btrim(p_reason)));
  PERFORM set_config('app.subscription_reason', '', true);
  PERFORM set_config('app.organisation_id', coalesce(prev, ''), true);
END
$$;

CREATE FUNCTION app_platform_set_organisation_status(org uuid, p_status "OrganisationStatus", p_reason text)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
DECLARE
  prev text := current_setting('app.organisation_id', true);
  current_status "OrganisationStatus";
BEGIN
  PERFORM app_platform_require();
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'give a reason' USING ERRCODE = 'check_violation';
  END IF;
  IF p_status NOT IN ('ACTIVE', 'SUSPENDED') THEN
    RAISE EXCEPTION 'platform administrators only suspend and reactivate' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('app.organisation_id', org::text, true);
  SELECT "status" INTO current_status FROM "organisations" WHERE "id" = org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such organisation' USING ERRCODE = 'no_data_found';
  END IF;
  IF current_status NOT IN ('ACTIVE', 'SUSPENDED') OR current_status = p_status THEN
    RAISE EXCEPTION 'an organisation that is % cannot become %', lower(current_status::text), lower(p_status::text)
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE "organisations" SET "status" = p_status, "updated_at" = now() WHERE "id" = org;
  INSERT INTO "audit_logs" ("id", "organisation_id", "actor_user_id", "action", "resource_type", "resource_id", "metadata")
  VALUES (gen_random_uuid(), org, app_current_user_id(),
          CASE WHEN p_status = 'SUSPENDED' THEN 'organisation.suspended' ELSE 'organisation.reactivated' END,
          'organisation', org::text, jsonb_build_object('reason', btrim(p_reason)));
  PERFORM set_config('app.organisation_id', coalesce(prev, ''), true);
END
$$;

REVOKE ALL ON "platform_admins" FROM PUBLIC;
GRANT SELECT ON "platform_admins" TO veyra_app;
GRANT EXECUTE ON FUNCTION app_platform_usage(uuid) TO veyra_app;
GRANT EXECUTE ON FUNCTION app_platform_set_subscription(uuid, text, "SubscriptionStatus", timestamptz, text) TO veyra_app;
GRANT EXECUTE ON FUNCTION app_platform_set_organisation_status(uuid, "OrganisationStatus", text) TO veyra_app;
